// @ts-check
/**
 * The pre-paint bootstrap: apply saved reading preferences and rewrite dates while the document is
 * still parsing, so nothing flashes and no date column starts out empty.
 *
 * This is the only script that blocks rendering, which is why it stays small and dependency-free.
 * The validation rules come from `#aggr-preferences`, generated by src/config/preferences.rs.
 */
(function () {
  "use strict";

  /** @type {Record<string, {initial: any, values?: any[], min?: number, max?: number, attribute?: string}>} */
  var schema = {};
  try {
    var declared = document.getElementById("aggr-preferences");
    schema = JSON.parse((declared && declared.textContent) || "{}");
  } catch (error) {
    schema = {};
  }

  function valid(key, value) {
    if (!Object.prototype.hasOwnProperty.call(schema, key)) return false;
    var rule = schema[key];
    if (rule.values) return rule.values.indexOf(value) !== -1;
    return Number.isInteger(value) && value >= rule.min && value <= rule.max;
  }

  /** Storage holds strings; restore the type the rule declares before validating. */
  function storedValue(key, value) {
    if (typeof schema[key].initial === "boolean")
      return value === "true" ? true : value === "false" ? false : null;
    if (typeof schema[key].initial === "number")
      return typeof value === "string" && /^\d+$/.test(value) ? Number(value) : null;
    return value;
  }

  function read() {
    var state = {};
    Object.keys(schema).forEach(function (key) {
      var value = null;
      try {
        value = localStorage.getItem("aggr:" + key);
      } catch (error) {
        /* private browsing */
      }
      value = storedValue(key, value);
      state[key] = valid(key, value) ? value : schema[key].initial;
    });
    return state;
  }

  /** Imports must be a `{version: 1, preferences: {…}}` envelope of known, valid settings. */
  function validate(payload) {
    if (!payload || typeof payload !== "object" || Array.isArray(payload))
      throw new Error("Invalid preferences");
    if (
      payload.version !== 1 ||
      Object.keys(payload).some(function (key) {
        return key !== "version" && key !== "preferences";
      })
    )
      throw new Error("Unsupported preferences version");
    var source = payload.preferences;
    if (!source || typeof source !== "object" || Array.isArray(source) || !Object.keys(source).length)
      throw new Error("Empty preferences");
    var state = {};
    Object.keys(source).forEach(function (key) {
      if (!valid(key, source[key])) throw new Error("Invalid preference: " + key);
      state[key] = source[key];
    });
    return state;
  }

  function apply(values) {
    Object.keys(schema).forEach(function (key) {
      var attribute = schema[key].attribute;
      if (attribute) document.documentElement.dataset[attribute] = String(values[key]);
    });
  }

  var values = read();
  apply(values);
  window.AGGRPreferences = {
    schema: schema,
    values: values,
    read: read,
    validate: validate,
    valid: valid,
    apply: apply,
  };

  /* ---------------------------------------------------------------- dates */

  var formatters = new Map();
  function formatter(name, options) {
    if (!formatters.has(name)) formatters.set(name, new Intl.DateTimeFormat(undefined, options));
    return formatters.get(name);
  }

  function text(timestamp, format) {
    if (!Number.isFinite(timestamp) || Number.isNaN(new Date(timestamp).getTime())) return null;
    if (format === "iso") return new Date(timestamp).toISOString().slice(0, 10);
    if (format === "local") return formatter("local", { dateStyle: "medium" }).format(timestamp);
    if (format === "local-time")
      return formatter("local-time", { dateStyle: "medium", timeStyle: "short" }).format(timestamp);
    var seconds = Math.max(0, Math.round((Date.now() - timestamp) / 1000));
    if (seconds < 60) return "just now";
    var minutes = Math.floor(seconds / 60);
    if (minutes < 60) return minutes + "m ago";
    var hours = Math.floor(minutes / 60);
    if (hours < 24) return hours + "h ago";
    var days = Math.floor(hours / 24);
    if (days < 45) return days + "d ago";
    var months = Math.floor(days / 30);
    if (months < 18) return months + "mo ago";
    return Math.floor(days / 365) + "y ago";
  }

  window.AGGRDates = { text: text };

  function format(time) {
    if (!time.textContent) return;
    var value = text(Date.parse(time.getAttribute("datetime") || ""), values["date-format"]);
    if (value && time.textContent !== value) time.textContent = value;
  }

  function collect(node, times, descendants) {
    var element = node.nodeType === 1 ? node : node.parentElement;
    if (!element) return;
    var time = element.closest("time[datetime]");
    if (time) times.add(time);
    if (descendants && node.nodeType === 1)
      element.querySelectorAll("time[datetime]").forEach(function (found) {
        times.add(found);
      });
  }

  function changed(records) {
    var times = new Set();
    records.forEach(function (record) {
      collect(record.target, times, false);
      record.addedNodes.forEach(function (node) {
        collect(node, times, true);
      });
    });
    times.forEach(format);
  }

  function all() {
    document.querySelectorAll("time[datetime]").forEach(format);
  }

  // While the document is still parsing, rewrite each date as it appears rather than waiting for
  // the end: a reader should never see the raw timestamp replaced under them.
  if (document.readyState === "loading") {
    var observer = new MutationObserver(changed);
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      characterData: true,
    });
    document.addEventListener(
      "DOMContentLoaded",
      function () {
        changed(observer.takeRecords());
        observer.disconnect();
        all();
      },
      { once: true },
    );
  }
  all();
})();
